local specialStruct = {
    NAMESPACE   = 1,
    STRUCT_NAME = 1,
    TYPE        = 1,
    NOTES       = 1,
    GROUPS      = 1,
}

-- upstream's %Image::ExifTool::UserDefined::xmpStruct -- the XMP structure
-- definitions a .ExifTool_config may declare by name.  A lexiftool config
-- file defines structures in place (see Port notes), so the table stays empty.
local xmpStruct = { }

-- (upstream inserts the user-defined and plug-in tags here; in Lua those two
--  blocks have to run after TagLookup.AddTags is defined, so they sit at the
--  bottom of this file)


--------------------------------------------------------------------------------
-- Add tag names to lookup corresponding to flattened XMP tags for all structure fields
-- Inputs: 0) tag table ref for flattened tags, 1) tagID, 2) lowercase tag name,
--         3) tag ID list ref, 4) reference to list of lowercase tag names
--         5) table number in lookup, 6) tagInfo hash for parent structure
--         7) tag ID of top-level structure
-- Notes: Used only for user-defined structures
function TagLookup.AddFields(tagTablePtr, tagID, lcTag, tagIDs, lcTags, tnum, tagInfo, baseID)
    if length(tagID) > 500 then return end    -- avoid deep recursion
    if not tagInfo then
        tagInfo = tagTablePtr[tagID]
        baseID = tagID
    end
    local strTable = tagInfo.Struct
    if type(strTable) ~= 'table' then
        local strName = strTable
        strTable = xmpStruct[strTable]
        if not strTable then
            perl.print(io.stderr, "No definition for structure '" .. str(strName) .. "'\n")
            return
        end
        if not perlTruthy(strTable.STRUCT_NAME) then strTable.STRUCT_NAME = 'XMP ' .. strName end
        tagInfo.Struct = strTable       -- replace name with hash ref
        tagInfo.SubDirectory = nil      -- deprecated use of SubDirectory in Struct tags
    end
    -- inherit NAMESPACE from parent table if it doesn't exist
    if strTable.NAMESPACE == nil then strTable.NAMESPACE = tagTablePtr.NAMESPACE end
    local field
    for f in pairs(strTable) do
        field = f
        if not specialStruct[field] then
            local id = tagID .. ucfirst(field)
            -- use name of existing flattened tag if already defined
            local flatInfo = tagTablePtr[id]
            local fieldInfo = strTable[field]
            local flatName
            if type(fieldInfo) == 'table' then flatName = fieldInfo.FlatName end
            if not perlTruthy(flatName) then
                flatName = field:gsub('[^%-_a-zA-Z0-9]', '')    -- remove illegal characters
            end
            local lc = (flatInfo and flatInfo.Name) and perlLc(flatInfo.Name) or lcTag .. perlLc(flatName)
            local copyID = baseID
            -- (upstream \$copyID: the ID in [1], the form of the generated
            --  lists above, and marked as a reference, so that a lone one is
            --  not taken for an ARRAY of IDs)
            tagIDs[#tagIDs + 1] = { copyID, ref = 'SCALAR' }
            tagIDs[#tagIDs + 1] = id
            lcTags[#lcTags + 1] = lc
            lcTags[#lcTags + 1] = lc
            if type(fieldInfo) == 'table' and fieldInfo.Struct then
                -- recursively add flattened tags for all sub-fields
                TagLookup.AddFields(tagTablePtr, id, lc, tagIDs, lcTags, tnum, fieldInfo, baseID)
            end
        end
    end
end

--------------------------------------------------------------------------------
-- Add tags to the lookup (for user-defined tags, etc)
-- Inputs: 0) tag table ref, 1) table name
local tableNumHash = { }
function TagLookup.AddTags(tagTablePtr, table_)

    -- generate lookup for table numbers if not done already
    if next(tableNumHash) == nil then
        local tnum = 1
        local tbl
        for _, t in ipairs(tableList) do
            tbl = t
            tableNumHash[tbl] = tnum
            tnum = tnum + 1
        end
    end
    local moreTables, moreTableRefs = { }, { }
    while true do
        local tnum = tableNumHash[table_]
        if tnum == nil then
            -- add new table to list
            tnum = #tableList + 1
            tableList[tnum] = table_
        end
        local tagID
        for _, id in ipairs(ExifTool.TagTableKeys(tagTablePtr)) do
            tagID = id
            local newInfo = tagTablePtr[tagID]
            if type(newInfo) == 'table' then
                if not perlTruthy(newInfo.Name) then newInfo.Name = ExifTool.MakeTagName(tagID) end
                -- use new ID of tag in Composite table in case it changed
                if newInfo.NewTagID ~= nil then tagID = newInfo.NewTagID end
            else
                newInfo = { Name = newInfo }
                tagTablePtr[tagID] = newInfo
            end
            local lcTag = perlLc(newInfo.Name)
            local lcTags, tagIDs, existed, isFlat = { }, { }, nil, nil
            -- if this is a structure, add all flattened tag names to lookup
            if newInfo.Struct then
                local lcFlat = newInfo.FlatName and perlLc(newInfo.FlatName) or lcTag
                TagLookup.AddFields(tagTablePtr, tagID, lcFlat, tagIDs, lcTags, tnum)
            end
            -- add tags to lookup even though we don't know if they are writable
            -- (to save speed by not having to load the module)
            while true do                                               -- Tags:
                local lookup = tagLookup[lcTag]
                if not lookup then
                    lookup = { }
                    tagLookup[lcTag] = lookup
                end
                if perlTruthy(lookup[tnum]) then
                    local le = lookup[tnum]
                    -- (a list of IDs, or a single ID -- which may itself be the
                    --  SCALAR reference to a base structure's ID)
                    local ids = (type(le) == 'table' and le.ref == nil) and le or { le }
                    if type(tagID) == 'table' then
                        -- a reference points to the tag ID of the base structure for
                        -- a flattened tag.  There must be only one of these,
                        -- and it must come first.
                        if type(ids[1]) ~= 'table' then table.insert(ids, 1, tagID) end
                    else
                        -- only add new tag ID if it didn't already exist
                        local found
                        for i = 1, #ids do
                            if ids[i] == tagID then found = 1; break end
                        end
                        if found then
                            if not isFlat then existed = 1 end
                        else
                            ids[#ids + 1] = tagID
                        end
                    end
                    -- only update lookup if there is now more than one entry
                    if #ids > 1 then lookup[tnum] = ids end
                else
                    lookup[tnum] = tagID
                end
                if #tagIDs == 0 then break end
                local lastTags
                while true do
                    tagID = remove(tagIDs, 1)
                    lcTag = remove(lcTags, 1)
                    if not perlTruthy(tagTablePtr[tagID]) then break end -- don't waste time if it exists
                    if #tagIDs == 0 then lastTags = 1; break end
                end
                if lastTags then break end                              -- last Tags
                isFlat = 1
            end
            -- add any new subdirectory tables (unless done already)
            if not existed and newInfo.SubDirectory then
                local subTable = newInfo.SubDirectory.TagTable
                if subTable and tableNumHash[subTable] == nil and not moreTableRefs[subTable] then
                    local subTablePtr = ExifTool.GetTagTable(nil, subTable)
                    if subTablePtr and next(subTablePtr) ~= nil then
                        -- save new table to process after this one
                        moreTables[#moreTables + 1] = subTable
                        moreTableRefs[subTable] = subTablePtr
                        -- save source table name so we can load it when necessary
                        subTablePtr.SRC_TABLE = table_
                    end
                end
            end
        end
        table_ = remove(moreTables, 1)
        if not table_ then break end
        tagTablePtr = moreTableRefs[table_]
    end
end

--------------------------------------------------------------------------------
-- Return true if the tag exists
-- Inputs: 0) tag name (case insensitive)
-- Returns: true if tag exists
function TagLookup.TagExists(tag)
    tag = perlLc(tag)
    if tagExists[tag] or tagLookup[tag] then return 1 end
    return 0
end

--------------------------------------------------------------------------------
-- Find information for writable tags (case insensitive)
-- Inputs: 0) tag name (case insensitive)
-- Returns: list of all matching tagInfo hashes (upstream returns the list in
--          list context and its first element in scalar context; Lua has no
--          wantarray, so the caller takes [1] for the scalar form)
function TagLookup.FindTagInfo(tag)
    local lcTag = perlLc(tag)
    local tableNum
    local tagInfoList, lookups = { }, { }
    local lookup = tagLookup[lcTag]
    if not lookup and lcTag:find('[?*]') then
        -- allow wildcards in tag name
        local pat = lcTag
        pat = subst(pat, [[\*]], [=[[-\w]*]=], 'g')
        pat = subst(pat, [[\?]], [=[[-\w]]=], 'g')
        local tags = { }
        for t in pairs(tagLookup) do
            if isMatchDyn(t, '^' .. pat .. '$') then tags[#tags + 1] = t end
        end
        if #tags > 0 then
            tsort(tags)
            for _, t in ipairs(tags) do lookups[#lookups + 1] = tagLookup[t] end
            lookup = remove(lookups, 1)
        end
    end
    while lookup do
        local tableNums = { }
        for n in pairs(lookup) do tableNums[#tableNums + 1] = n end
        tsort(tableNums)
        for _, n in ipairs(tableNums) do
            tableNum = n
            -- (a table that cannot be loaded, e.g. one a config file names
            --  wrongly, is undef upstream, whose tag lookups then find nothing)
            local table_ = ExifTool.GetTagTable(nil, tableList[tableNum]) or { }
            local le = lookup[tableNum]
            local tagID, tagIDs
            if type(le) == 'table' and le.ref == nil then
                tagIDs = le
                -- if first entry is a reference, it indicates that this is a
                -- flattened tag and refers to the tag ID of the containing top-level
                -- structure, so now is the time to generate the flattened tags
                if type(tagIDs[1]) == 'table' then
                    -- (remove from the lookup since we only need to do this once)
                    local rootIDPtr = remove(tagIDs, 1)
                    local XMP = require('lexiftool.XMP')
                    XMP.AddFlattenedTags(table_, rootIDPtr[1])
                end
            else
                tagIDs = { le }
            end
            for _, id in ipairs(tagIDs) do
                tagID = id
                -- (port: Perl hash keys are strings, so the lookup's '14.1'
                --  names the table's numeric 14.1 key -- a Lua table keeps the
                --  two apart)
                if type(tagID) == 'string' and table_[tagID] == nil and tonumber(tagID) and
                    table_[tonumber(tagID)] ~= nil
                then
                    tagID = tonumber(tagID)
                end
                local infoList = ExifTool.GetTagInfoList(table_, tagID)
                if #infoList == 0 then
                    local reload
                    -- call write proc if it exists in case it adds tags to the table
                    local writeProc = table_.WRITE_PROC
                    if writeProc then
                        if perlTruthy(writeProc()) then reload = 1 end
                    end
                    -- load module with composite tag if necessary
                    local compMod = compositeModules[lcTag]
                    if compMod and pcall(require, compMod) then reload = 1 end
                    if reload then infoList = ExifTool.GetTagInfoList(table_, tagID) end
                end
                if #infoList == 1 then
                    tagInfoList[#tagInfoList + 1] = infoList[1]
                elseif #infoList > 1 then
                    local tagInfo
                    -- must check tag list in case tags have different names
                    for _, ti in ipairs(infoList) do
                        tagInfo = ti
                        if lcTag == perlLc(tagInfo.Name) then
                            tagInfoList[#tagInfoList + 1] = tagInfo
                        end
                    end
                end
            end
        end
        lookup = remove(lookups, 1)
    end
    return tagInfoList
end

-- (upstream position: directly after the generated code above)

-- insert any user-defined tags into our tag lookup
if ExifTool.UserDefined then
    local userTables = { }
    for t in pairs(ExifTool.UserDefined) do userTables[#userTables + 1] = t end
    tsort(userTables)
    while #userTables > 0 do
        local table_ = remove(userTables, 1)
        TagLookup.AddTags(ExifTool.UserDefined[table_], table_)
    end
end

-- insert any other queued tags from plug-in modules
if ExifTool.pluginTags then
    local args
    for _, a in ipairs(ExifTool.pluginTags) do
        args = a
        TagLookup.AddTags(args[1], args[2])
    end
    ExifTool.pluginTags = nil
end

return TagLookup
